/*******************************
 * Dialog: choose Push / Pull (caster-centered)
 * - 参考点 = 当前控制的施法者 token（必须先控制）
 * - 弹窗只需选择 Push/Away or Pull/Toward
 * - 默认距离 DEFAULT_FEET 内置，无需在对话中设置
 * - 使用 MidiQOL.moveTokenFromPoint(..., animate=true)
 *******************************/
(async () => {
  const DEFAULT_FEET = 15;
  const gs = canvas.grid.size;
  const feetPerSquare = canvas.scene.grid?.distance ?? 5;

  function getTargets() {
    const t = Array.from(game.user.targets ?? []);
    if (t.length) return t;
    return canvas.tokens.controlled.filter(tok => true);
  }
  function getTokenCenter(t) { return { x: (t.center?.x ?? (t.x + t.w/2)), y: (t.center?.y ?? (t.y + t.h/2)) }; }
  function getTokenGridSize(t) { return { w: Math.max(1, Math.floor(Number(t.document?.width ?? t.document?._source?.width ?? 1))), h: Math.max(1, Math.floor(Number(t.document?.height ?? t.document?._source?.height ?? 1))) }; }
  function snapCenterForToken(rawCenter, tokenGridW, tokenGridH) {
    const S = CONST.GRID_SNAPPING_MODES;
    let cell;
    try { cell = canvas.grid.getSnappedPoint({ x: rawCenter.x, y: rawCenter.y }, { mode: S.CENTER, resolution: 1 }); }
    catch(e) { cell = { x: Math.round(rawCenter.x / gs) * gs, y: Math.round(rawCenter.y / gs) * gs }; }
    const snapX = (tokenGridW % 2 === 1) ? cell.x : Math.round(rawCenter.x / gs) * gs;
    const snapY = (tokenGridH % 2 === 1) ? cell.y : Math.round(rawCenter.y / gs) * gs;
    const col = Math.floor(snapX / gs), row = Math.floor(snapY / gs);
    const topLeftCol = col - Math.floor(tokenGridW / 2), topLeftRow = row - Math.floor(tokenGridH / 2);
    const centerX = Math.round((topLeftCol + tokenGridW/2) * gs), centerY = Math.round((topLeftRow + tokenGridH/2) * gs);
    return { center: { x: centerX, y: centerY }, topLeft: { x: Math.round(topLeftCol * gs), y: Math.round(topLeftRow * gs) } };
  }

  // get caster
  const caster = canvas.tokens.controlled[0] ?? token ?? null;
  if (!caster) { ui.notifications.warn("请先控制施法者的 Token 再运行此宏"); return; }
  const casterCenter = getTokenCenter(caster);
  // targets
  const targets = getTargets().filter(t => t.id !== caster.id);
  if (!targets.length) { ui.notifications.warn("未发现目标（targets 或被控制 tokens）"); return; }

  // dialog: choose push or pull
  const choice = await new Promise(resolve => {
    new Dialog({
      title: "选择 强制位移 方向",
      content: `<p>选择是将目标推离施法者（push），还是拉近施法者（pull）？</p>`,
      buttons: {
        pull: { label: "拉近 (Toward)", callback: () => resolve("toward") },
        push: { label: "推离 (Away)", callback: () => resolve("away") },
        cancel: { label: "取消", callback: () => resolve(null) }
      },
      default: "pull"
    }).render(true);
  });
  if (!choice) return ui.notifications.info("已取消");

  for (const tk of targets) {
    try {
      const distFeet = DEFAULT_FEET;
      const moveDistanceArg = (choice === "away") ? Math.abs(distFeet) : -Math.abs(distFeet); // positive=away, negative=toward
      if (typeof MidiQOL?.moveTokenFromPoint === "function") {
        await MidiQOL.moveTokenFromPoint(tk, moveDistanceArg, casterCenter);
      } else {
        // fallback: compute raw toward/toward center and animate via moveToken
        const cur = getTokenCenter(tk);
        const vx = (casterCenter.x - cur.x) || 1;
        const vy = (casterCenter.y - cur.y) || 0;
        const norm = Math.hypot(vx, vy) || 1;
        const raw = { x: Math.round(cur.x + (vx/norm) * pxFromFeet(distFeet)), y: Math.round(cur.y + (vy/norm) * pxFromFeet(distFeet)) };
        await MidiQOL.moveToken(tk, raw, true);
      }

      // wait short for animation, then snap quietly
      await new Promise(r => setTimeout(r, 250));
      const { w: tgW, h: tgH } = getTokenGridSize(tk);
      const curCenter = getTokenCenter(tk);
      const snap = snapCenterForToken(curCenter, tgW, tgH);
      if (Math.abs(curCenter.x - snap.center.x) > 1 || Math.abs(curCenter.y - snap.center.y) > 1) {
        await MidiQOL.moveToken(tk, { x: snap.center.x, y: snap.center.y }, false);
      }

      ChatMessage.create({ content: `${tk.name} 已被 ${choice === "away" ? "推离" : "拉近"} (${DEFAULT_FEET} ft)` });
    } catch (e) {
      console.error("Dialog push/pull failed", e);
      ChatMessage.create({ content: `${tk.name} 的移动失败` });
    }
  }

  function pxFromFeet(feet) { return (feet / feetPerSquare) * gs; }
})();
